  // A site whose home has none opens on the first scenes page.
  const STAGES = (D.pages || []).filter((p) => p.type === 'scenes');
  const HOME_ROWS = D.rows.length ? D.rows : (STAGES[0] ? STAGES[0].rows : []);
  let ROWS = HOME_ROWS, stageId = '';
  const SMALL = matchMedia('(max-width: 760px)').matches;
